# The number of pending requests allowed
CONFIG_RTIO_WORKQ_POOL_ITEMS=2

# Configure RTIO copy pool to be very small to ensure exhaustion for testing.
# Setting CONFIG_RTIO_SQE_COPY_POOL_SIZE=1 ensures that only one copy buffer
# can be allocated, leading to exhaustion on subsequent requests.
# Leaving CONFIG_RTIO_SQE_COPY_POOL_BUFFER_SIZE at its default (e.g., 128 bytes)
# prevents potential crashes related to requesting buffers smaller than the
# driver's internal minimums while still ensuring pool exhaustion by count.
CONFIG_RTIO_SQE_COPY_POOL_SIZE=1

# Used for debugging
CONFIG_I2C_LOG_LEVEL_DBG=y
CONFIG_I2C_DUMP_MESSAGES=y
